// Символы для случайного пароля
const chars = {
    lowercase: 'abcdefghijklmnopqrstuvwxyz',
    uppercase: 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
    numbers: '0123456789',
    symbols: '!@#$%^&*()_+-=[]{}|;:,.<>?'
};

// Инициализация при загрузке
document.addEventListener('DOMContentLoaded', function() {
    initializeTabs();
    //initializeRangeSliders();
    initializeGenerators();
    initializeCopyFunction();
    initializeModal();
});

function initializeTabs() {
    const tabButtons = document.querySelectorAll('.tab-button');
    const tabPanes = document.querySelectorAll('.tab-pane');

    tabButtons.forEach(button => {
        button.addEventListener('click', () => {
            const targetTab = button.getAttribute('data-tab');
            
            // Убираем активный класс со всех кнопок и панелей
            tabButtons.forEach(btn => btn.classList.remove('active'));
            tabPanes.forEach(pane => pane.classList.remove('active'));
            
            // Добавляем активный класс к выбранным
            button.classList.add('active');
            document.getElementById(targetTab).classList.add('active');
        });
    });
}

function initializeRangeSliders() {
    // Слайдер длины случайного пароля
    const randomLengthSlider = document.getElementById('randomLength');
    const randomLengthValue = document.getElementById('randomLengthValue');
    
    randomLengthSlider.addEventListener('input', () => {
        randomLengthValue.textContent = randomLengthSlider.value;
    });

    // Слайдер количества слов
    const wordCountSlider = document.getElementById('wordCount');
    const wordCountValue = document.getElementById('wordCountValue');
    
    wordCountSlider.addEventListener('input', () => {
        wordCountValue.textContent = wordCountSlider.value;
    });

    // Слайдер длины PIN
    const pinLengthSlider = document.getElementById('pinLength');
    const pinLengthValue = document.getElementById('pinLengthValue');
    
    pinLengthSlider.addEventListener('input', () => {
        pinLengthValue.textContent = pinLengthSlider.value;
    });
}

function initializeGenerators() {
    // Генерация случайного пароля
    document.getElementById('generateRandom').addEventListener('click', () => {
        const length = parseInt(document.getElementById('randomLength').value);
        const useNumbers = document.getElementById('addNumbers').checked;
        const useSymbols = document.getElementById('addSpecSymbols').checked;
        const password = generateRandomPassword(length, useNumbers, useSymbols);
        displayPassword(password);
    });

    // Генерация запоминаемого пароля
    document.getElementById('generateMemorable').addEventListener('click', () => {
        const wordCount = parseInt(document.getElementById('wordCount').value);
        const addSymbols = document.getElementById('addSymbols').checked;;
        const password = generateMemorablePassword(wordCount, addSymbols);
        displayPassword(password);
    });

    // Генерация PIN
    document.getElementById('generatePin').addEventListener('click', () => {
        const length = parseInt(document.getElementById('pinLength').value);
        const pin = generatePin(length);
        displayPassword(pin);
    });
}

function generateRandomPassword(length, useNumbers = false, useSymbols= false) {    
    const allChars = chars.lowercase + chars.uppercase + (useNumbers ? chars.numbers : '') + ( useSymbols ? chars.symbols : '');
    let password = '';
    
    // Обеспечиваем наличие по крайней мере одного символа каждого типа
    password += getRandomChar(chars.lowercase);
    password += getRandomChar(chars.uppercase);
    if (useNumbers) password += getRandomChar(chars.numbers);
    if (useSymbols) password += getRandomChar(chars.symbols);
    
    // Заполняем оставшуюся длину случайными символами
    for (let i = 4; i < length; i++) {
        password += getRandomChar(allChars);
    }
    
    // Перемешиваем символы
    return shuffleString(password);
}

function generateMemorablePassword(wordCount, addSymbols = false) {
    let password = [];
    
    for (let i = 0; i < wordCount; i++) {
        const randomIndex = Math.floor(Math.random() * commonWords.length);
        password.push(commonWords[randomIndex]);
    }
    
    let result = password.join('-');
    
    // Добавляем случайные символы в конце, если выбрана опция
    if (addSymbols) {
        const symbolCount = Math.floor(Math.random() * 3) + 2; // 2-4 символа
        let extraSymbols = '';
        
        for (let i = 0; i < symbolCount; i++) {
            extraSymbols += getRandomChar(chars.numbers + chars.symbols);
        }
        
        result += '-' + extraSymbols;
    }
    
    return result;
}

function generatePin(length) {
    let pin = '';
    
    for (let i = 0; i < length; i++) {
        pin += Math.floor(Math.random() * 10);
    }
    
    return pin;
}

function getRandomChar(str) {
    return str.charAt(Math.floor(Math.random() * str.length));
}

function shuffleString(str) {
    return str.split('').sort(() => Math.random() - 0.5).join('');
}

function displayPassword(password) {
    const passwordField = document.getElementById('generatedPassword');
    passwordField.value = password;
    
    // // Добавляем небольшую анимацию
    // passwordField.style.transform = 'scale(1.02)';
    // setTimeout(() => {
    //     passwordField.style.transform = 'scale(1)';
    // }, 150);
}

function initializeCopyFunction() {
    document.getElementById('copyPassword').addEventListener('click', () => {
        const passwordField = document.getElementById('generatedPassword');
        const copyMessage = document.getElementById('copyMessage');
        
        if (passwordField.value) {
            // Копируем в буфер обмена
            passwordField.select();
            document.execCommand('copy');
            
            // Показываем сообщение
            copyMessage.classList.add('show');
            
            // Скрываем сообщение через 2 секунды
            setTimeout(() => {
                copyMessage.classList.remove('show');
            }, 2000);
            
            // Анимация кнопки
            const copyBtn = document.getElementById('copyPassword');
            copyBtn.style.background = '#20c997';
            setTimeout(() => {
                copyBtn.style.background = '#28a745';
            }, 200);
        }
    });
}

function initializeModal() {
    const modal = document.getElementById('modal');
    const infoBtn = document.getElementById('infoBtn');
    const closeBtn = document.querySelector('.close');

    // Открытие модального окна
    infoBtn.addEventListener('click', () => {
        console.log("OPEN");
        modal.classList.add('show');
    });

    // Закрытие модального окна
    closeBtn.addEventListener('click', () => {
     console.log("CLOSE");   
     modal.classList.remove('show');
    });

    // Закрытие при клике вне модального окна
    window.addEventListener('click', (event) => {
        if (event.target === modal) {
            modal.classList.remove('show');
        }
    });

    // Открытие ссылок в новых вкладках
    document.querySelectorAll('.link-btn').forEach(link => {
        link.addEventListener('click', (e) => {
            e.preventDefault();
            const url = link.getAttribute('href');
            
            if (url.startsWith('mailto:')) {
                window.location.href = url;
            } else {
                chrome.tabs.create({ url: url });
            }
        });
    });
}